reg06_in(31 downto  0) <= fifo_rdata;--fifo read data
reg07_in(15 downto  0) <= fifo_wr_size;--fifo size for write access
reg08_in(15 downto  0) <= fifo_rd_size;--fifo size for read access
reg0B_in(31 downto  0) <= dma_wrptr;--dma write pointer (tracks dma write bursts)
reg0C_in(31 downto  0) <= dma_rdptr;--dma read pointer (tracks dma read bursts)
reg14_in(0) <= sounding_ready;--1= sounding fsm ready for measurement
reg16_in( 7 downto  0) <= gpio_i;--Digital Inputs
reg18_in(31 downto  0) <= i2c_luxmeter;--luxmeter reading
reg1D_in(31 downto  0) <= dsp_envelope;--rectified and integrated audio iput signal
reg1E_in(31 downto  0) <= fifo2_rdata;--audio fifo read data
reg20_in(15 downto  0) <= fifo2_tx_size;--audio fifo  size in tx path
reg20_in(31 downto 16) <= fifo2_tx_waddr;--audio fifo write address in tx path
reg21_in(15 downto  0) <= fifo2_rx_size;--audio fifo size in rx path
reg21_in(31 downto 16) <= fifo2_rx_waddr;--audio fifo write address in tx path
--rd_regs_off

--wr_regs_on
leds                 <= reg01( 3 downto  0);--4 zybo leds
fxgen_level          <= reg02(15 downto  0);--function generator signal level
fxgen_offset         <= reg02(31 downto 16);--function generator signal offset
fxgen_fcw            <= reg03(31 downto  0);--function generator frequency control word
fxgen_wavsel         <= reg04( 3 downto  0);--function generator waveform selection
audio_select         <= reg04(4);--select audio for audio dsp input
line_select          <= reg04(5) and we(4);--select line in
mic_select           <= reg04(6) and we(4);--select microphone in
test_in_left         <= reg04(8);--force test signal on left audio input
test_in_right        <= reg04(9);--force test signal on right audio input
test_out_left        <= reg04(10);--force test signal on left audio output
test_out_right       <= reg04(11);--force test signal on right audio output
audio_loop_en        <= reg04(7);--enable audio loop
audio_in_scale       <= reg04(15 downto 12);--barrel shifter to amplify audio input
audio_mute_left      <= reg04(16);--mute left audio out
audio_mute_right     <= reg04(17);--mute right audio out
fifo_rd_stb          <= rd(6);--fifo read strobe (generated inside fpga on fifo read)
fifo_wdata           <= reg06(31 downto  0);--fifo write data
fifo_wr_stb          <= we(6);--fifo write strobe (generated inside fpga on fifo write)
buzzer_select        <= reg09( 1 downto  0);--0 = buzzer controlled by dds   1 = buzzer controlled by register  2 = buzzer morsecode
buzzer_reg           <= reg09(4);--buzzer on/off controlled by register
dma_rate_fcw         <= reg0A(29 downto  0);--conversion factor = 2**30 / 100e6 = 10.737       fcw = 10737 --> f = 1kHz
dma_rd_en            <= reg0A(30);--enable the dma read transfer
dma_wr_en            <= reg0A(31);--enable the dma write transfer
dma_rd_select        <= reg0D( 1 downto  0);--00 = audio   others  = TBD
dma_rd_sampling      <= reg0D(3);--0 = dma_rate_fcw determines sample rate  1 = native audio samples
dma_wr_select        <= reg0D( 5 downto  4);--00 = audio   others  = dma_testpattern
dma_wr_sampling      <= reg0D(6);--0 = dma_rate_fcw determines sample rate  1 = native audio samples
dma_testpattern      <= reg0E(31 downto  0);--testpattern for dma write transfer testing
pmod_o               <= reg0F( 7 downto  0);--8-bit parallel digital output
pmod_o_select        <= reg0F(8);--0 = pmod_o   1 =  debug outputs
snd_pulse_period     <= reg11(15 downto  0);--sounding pulse period in audio samples @48kHz
snd_pulse_length     <= reg11(31 downto 16);--sounding pulse length in audio samples @48kHz
snd_pulse_repetitions <= reg12( 7 downto  0);--sound pulse repetition number
snd_trig             <= we(18);--trigger to send sound pulses
buzzer_fcw           <= reg13(26 downto  0);--conversion factor = 2**27 / 100e6 = 1.34       fcw = 1342 --> f = 1kHz
gpio_o               <= reg15( 7 downto  0);--Digital Outputs
gpio_dir             <= reg15(15 downto  8);--0 = output   1 = input  gpio direction
light_barrier_1_mux  <= reg17( 2 downto  0);--select light barrier 1 gpio input
light_barrier_2_mux  <= reg17( 6 downto  4);--select light barrier 2 gpio input
speed_trap_en        <= reg17(8);--enable speed trap measurements
speed_trap_guard_time <= reg17(31 downto 16);--minimum time in usec for light barrier interruption
luxmeter_trigger     <= reg18(0);--start luxmeter
disp_data            <= reg1A(31 downto  0);--32-bit BCD coded or binary data for 8 display digits
disp_dp              <= reg1B( 7 downto  0);--8 decimal points  0 = off  1 = on
disp_blank           <= reg1B(15 downto  8);--individual  digit blanking  0 = digit ON   1 = digit OFF
dsp_dump             <= reg1C( 7 downto  0);--number of audio samples to be integrated per dump
dsp_scale            <= reg1C(10 downto  8);--barrell shifter to scale audio signal integration result
dsp_dump_sel         <= reg1C(16);--0 = use register read to dump   1 = use dsp_dump value to dump
dsp_dump_stb         <= rd(29);--strobe to dump audio signal
fifo2_rd_stb         <= rd(30);--audio fifo read strobe
fifo2_wdata          <= reg1E(31 downto  0);--audio fifo write data
fifo2_wr_stb         <= we(30);--audio fifo write strobe
fifo2_en             <= reg1F(0);--audio fifo enable
fifo2_reset          <= reg1F(1);--audio fifo_reset
fifo2_rxtrig         <= reg1F(2) and we(31);--audio fifo receive trigger
fifo2_rx_stream      <= reg20(3);--audio fifo read continuous stream
--wr_regs_off
   
  
end architecture rtl;

